CREATE TABLE currencies (code text PRIMARY KEY CHECK(code ~ '^[A-Z]{3}$'), decimals integer NOT NULL DEFAULT 2 CHECK(decimals BETWEEN 0 AND 6));
CREATE TABLE companies (id uuid PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), base_currency text NOT NULL REFERENCES currencies(code), allow_negative_stock boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE company_currencies (company_id uuid REFERENCES companies(id), code text REFERENCES currencies(code), rate numeric(24,10) NOT NULL CHECK(rate > 0), PRIMARY KEY(company_id,code));
CREATE TABLE branches (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), name text NOT NULL, UNIQUE(company_id,id));
CREATE TABLE warehouses (id uuid PRIMARY KEY, company_id uuid NOT NULL, branch_id uuid NOT NULL, name text NOT NULL, UNIQUE(company_id,id), FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id));
CREATE TABLE permissions (id text PRIMARY KEY);
CREATE TABLE roles (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), name text NOT NULL, is_admin boolean NOT NULL DEFAULT false, UNIQUE(company_id,id), UNIQUE(company_id,name));
CREATE TABLE role_permissions (role_id uuid REFERENCES roles(id), permission_id text REFERENCES permissions(id), PRIMARY KEY(role_id,permission_id));
CREATE TABLE users (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), username text NOT NULL, name text NOT NULL, password_hash text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,id));
CREATE UNIQUE INDEX users_username ON users(lower(username));
CREATE TABLE user_roles (company_id uuid NOT NULL, user_id uuid NOT NULL, role_id uuid NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id), FOREIGN KEY(company_id,role_id) REFERENCES roles(company_id,id));
CREATE TABLE user_branches (company_id uuid NOT NULL, user_id uuid NOT NULL, branch_id uuid NOT NULL, PRIMARY KEY(user_id,branch_id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id), FOREIGN KEY(company_id,branch_id) REFERENCES branches(company_id,id));
CREATE TABLE user_warehouses (company_id uuid NOT NULL, user_id uuid NOT NULL, warehouse_id uuid NOT NULL, PRIMARY KEY(user_id,warehouse_id), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id), FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id));
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id), csrf_token text NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_expiry ON sessions(expires_at);
CREATE TABLE login_attempts (key text PRIMARY KEY, failures integer NOT NULL DEFAULT 0, window_start timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories (company_id uuid NOT NULL REFERENCES companies(id), id text NOT NULL, name text NOT NULL, PRIMARY KEY(company_id,id));
CREATE TABLE tax_configurations (company_id uuid NOT NULL REFERENCES companies(id), id text NOT NULL, name text NOT NULL, rate numeric(9,6) NOT NULL CHECK(rate BETWEEN 0 AND 100), price_includes_tax boolean NOT NULL DEFAULT false, PRIMARY KEY(company_id,id));
CREATE TABLE product_types (id text PRIMARY KEY CHECK(id IN ('stock','service','nonStock')));
INSERT INTO product_types VALUES ('stock'),('service'),('nonStock');
CREATE TABLE products (company_id uuid NOT NULL REFERENCES companies(id), id text NOT NULL, name text NOT NULL, type text NOT NULL REFERENCES product_types(id), sku text, category_id text, tax_id text, currency text NOT NULL REFERENCES currencies(code), allow_fractional boolean NOT NULL DEFAULT false, archived_at timestamptz, version integer NOT NULL DEFAULT 1, data jsonb NOT NULL CHECK(jsonb_typeof(data)='object'), PRIMARY KEY(company_id,id), FOREIGN KEY(company_id,category_id) REFERENCES categories(company_id,id), FOREIGN KEY(company_id,tax_id) REFERENCES tax_configurations(company_id,id));
CREATE UNIQUE INDEX product_sku ON products(company_id,sku) WHERE sku IS NOT NULL;
CREATE INDEX product_name_search ON products(company_id,lower(name) text_pattern_ops);
CREATE INDEX product_category ON products(company_id,category_id) WHERE archived_at IS NULL;
CREATE TABLE units_of_measure (company_id uuid NOT NULL REFERENCES companies(id), id text NOT NULL, name text NOT NULL, PRIMARY KEY(company_id,id));
CREATE TABLE product_units (company_id uuid NOT NULL, product_id text NOT NULL, id text NOT NULL, name text NOT NULL, factor numeric(24,9) NOT NULL CHECK(factor > 0), price numeric(24,9) NOT NULL CHECK(price >= 0), sell boolean NOT NULL, purchase boolean NOT NULL, is_base boolean NOT NULL, PRIMARY KEY(company_id,product_id,id), FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id), CHECK(NOT is_base OR factor=1));
CREATE UNIQUE INDEX one_base_unit ON product_units(company_id,product_id) WHERE is_base;
CREATE TABLE product_attributes (company_id uuid NOT NULL, product_id text NOT NULL, name text NOT NULL, attribute_values jsonb NOT NULL CHECK(jsonb_typeof(attribute_values)='array'), PRIMARY KEY(company_id,product_id,name), FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id));
CREATE TABLE product_variants (company_id uuid NOT NULL, product_id text NOT NULL, id text NOT NULL, sku text, attribute_values jsonb NOT NULL CHECK(jsonb_typeof(attribute_values)='object'), price numeric(24,9) NOT NULL CHECK(price >= 0), PRIMARY KEY(company_id,product_id,id), UNIQUE(company_id,sku), FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id));
CREATE TABLE variant_unit_prices (company_id uuid NOT NULL, product_id text NOT NULL, variant_id text NOT NULL, unit_id text NOT NULL, price numeric(24,9) NOT NULL CHECK(price >= 0), PRIMARY KEY(company_id,product_id,variant_id,unit_id), FOREIGN KEY(company_id,product_id,variant_id) REFERENCES product_variants(company_id,product_id,id), FOREIGN KEY(company_id,product_id,unit_id) REFERENCES product_units(company_id,product_id,id));
CREATE TABLE product_barcodes (company_id uuid NOT NULL, barcode text NOT NULL CHECK(length(barcode) BETWEEN 1 AND 200), product_id text NOT NULL, unit_id text, variant_id text, PRIMARY KEY(company_id,barcode), FOREIGN KEY(company_id,product_id) REFERENCES products(company_id,id), FOREIGN KEY(company_id,product_id,unit_id) REFERENCES product_units(company_id,product_id,id), FOREIGN KEY(company_id,product_id,variant_id) REFERENCES product_variants(company_id,product_id,id));
CREATE TABLE stock_balances (company_id uuid NOT NULL, product_id text NOT NULL, variant_id text NOT NULL DEFAULT '', warehouse_id uuid NOT NULL, quantity numeric(24,9) NOT NULL DEFAULT 0, average_cost numeric(24,9) NOT NULL DEFAULT 0 CHECK(average_cost >= 0), PRIMARY KEY(company_id,product_id,variant_id,warehouse_id), FOREIGN KEY(company_id,product_id,variant_id) REFERENCES product_variants(company_id,product_id,id), FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id));
CREATE TABLE stock_ledger (id uuid PRIMARY KEY, company_id uuid NOT NULL, product_id text NOT NULL, variant_id text NOT NULL DEFAULT '', warehouse_id uuid NOT NULL, quantity numeric(24,9) NOT NULL CHECK(quantity<>0), original_quantity numeric(24,9) NOT NULL CHECK(original_quantity<>0), unit_id text NOT NULL, unit_factor numeric(24,9) NOT NULL CHECK(unit_factor>0), kind text NOT NULL CHECK(kind IN ('opening','receipt','issue','adjustment','return')), reference text NOT NULL CHECK(length(reference) BETWEEN 1 AND 200), line_key text NOT NULL, unit_cost numeric(24,9) NOT NULL CHECK(unit_cost>=0), balance_after numeric(24,9) NOT NULL, average_cost_after numeric(24,9) NOT NULL CHECK(average_cost_after>=0), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,reference,line_key), FOREIGN KEY(company_id,product_id,variant_id) REFERENCES product_variants(company_id,product_id,id), FOREIGN KEY(company_id,product_id,unit_id) REFERENCES product_units(company_id,product_id,id), FOREIGN KEY(company_id,warehouse_id) REFERENCES warehouses(company_id,id), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id), CHECK(quantity=original_quantity*unit_factor), CHECK(kind NOT IN ('opening','receipt','return') OR quantity>0), CHECK(kind<>'issue' OR quantity<0));
CREATE INDEX ledger_history ON stock_ledger(company_id,warehouse_id,created_at DESC,id);
CREATE TABLE module_configuration (company_id uuid NOT NULL REFERENCES companies(id), module_id text NOT NULL, enabled boolean NOT NULL DEFAULT false, settings jsonb NOT NULL DEFAULT '{}', PRIMARY KEY(company_id,module_id));
CREATE TABLE audit_logs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), user_id uuid, action text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(company_id,user_id) REFERENCES users(company_id,id));
CREATE INDEX audit_history ON audit_logs(company_id,created_at DESC);
CREATE TABLE idempotency_requests (company_id uuid NOT NULL REFERENCES companies(id), key text NOT NULL, operation text NOT NULL, request_hash text NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(company_id,key));
CREATE TABLE import_batches (id uuid PRIMARY KEY, company_id uuid NOT NULL REFERENCES companies(id), content_hash text NOT NULL, original_products jsonb NOT NULL, report jsonb NOT NULL, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(company_id,content_hash), FOREIGN KEY(company_id,created_by) REFERENCES users(company_id,id));
